// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/odds_and_evens.sol";

contract OddsAndEvensTest is Test {
    OddsAndEvens public game;
    address payable public player1 = payable(address(0x100));
    address payable public player2 = payable(address(0x200));
    uint256 public constant MAX_UINT = type(uint256).max;

    function setUp() public {
        game = new OddsAndEvens();
        deal(player1, 2 ether);
        deal(player2, 1 ether);
    }

    function testArithmeticOverflow() public {
        uint256 player1StartBalance = player1.balance;
        uint256 player2StartBalance = player2.balance;

        // Player 1 sets max possible number to cause overflow
        vm.prank(player1);
        game.play{value: 1 ether}(MAX_UINT);

        // Player 2 sets the minimal increment value
        vm.prank(player2);
        game.play{value: 1 ether}(1); // Triggers arithmetic overflow

        // After overflow (MAX_UINT+1=0 which is even), player1 should win
        uint256 player1WinAmt = 1.8 ether;

        assertEq(
            player1.balance, 
            player1StartBalance - 1 ether + player1WinAmt,
            "Player1 should have starting balance - stake + winnings"
        );
        assertEq(
            player2.balance,
            player2StartBalance - 1 ether,
            "Player2 should only lose their stake"
        );

        // Verify win count (ignore gamesPlayed since contract only tracks globally)
        (uint wins1,) = game.getPlayerStats(player1);
        assertEq(wins1, 1, "Player1 should have 1 win");
    }
}
